  valid <- list("OdeRunner<FF16>"="FF16", "OdeRunner<TF24>"="TF24", "OdeRunner<TF24f>"="TF24f", "OdeRunner<K93>"="K93")
  constructors <- list("OdeRunner<FF16>"=`OdeRunner<FF16>`, "OdeRunner<TF24>"=`OdeRunner<TF24>`, "OdeRunner<TF24f>"=`OdeRunner<TF24f>`, "OdeRunner<K93>"=`OdeRunner<K93>`)
  constructors[[check_type(type, valid)]]
}
