Individual <- function(T, E) {
  type <- c(T, E)
  valid <- list("Individual<FF16,FF16_Env>"=c("FF16", "FF16_Env"), "Individual<TF24,TF24_Env>"=c("TF24", "TF24_Env"), "Individual<TF24f,TF24_Env>"=c("TF24f", "TF24_Env"), "Individual<K93,K93_Env>"=c("K93", "K93_Env"))
  constructors <- list("Individual<FF16,FF16_Env>"=`Individual<FF16,FF16_Env>`, "Individual<TF24,TF24_Env>"=`Individual<TF24,TF24_Env>`, "Individual<TF24f,TF24_Env>"=`Individual<TF24f,TF24_Env>`, "Individual<K93,K93_Env>"=`Individual<K93,K93_Env>`)
  constructors[[check_type(type, valid)]]
}
